function comparableName(value: string): string {
  return value.trim().replace(/^(Tỉnh|Tp|Thành phố)\s+/u, "").normalize("NFD").replace(/\p{Diacritic}/gu, "").toLocaleLowerCase("vi-VN");
}

export function findProvinceByName(name: string | undefined | null): ProvinceOption | undefined {
  return name ? PROVINCES.find((province) => comparableName(province.name) === comparableName(name)) : undefined;
}

export function getCommunesByProvinceName(name: string | undefined | null): readonly CommuneOption[] {
  const province = findProvinceByName(name);
  return province ? COMMUNES.filter((commune) => commune.provinceCode === province.code) : [];
}
